<div class="g g4">${TEAM.map((t,i)=>{const m=ls.filter(l=>l.own===t.id);return`<div class="panel tm-c rv"><div class="r1">${av(t.n,'l',t.h)}<div><b>${t.n}</b><small>${t.r}</small></div><span class="on-dot ${t.st==='aw'?'aw':t.st==='of'?'of':''}" title="${t.st==='on'?'Online':t.st==='aw'?'Away':'Offline'}"></span></div><div class="stats"><div><b>${m.length}</b><small class="mu">Leads</small></div><div><b>${m.filter(l=>l.st==='won').length}</b><small class="mu">Won</small></div><div><b>${[2.9,3.6,4.8,6.2][i]}m</b><small class="mu">Reply</small></div></div><div class="tags">${['Inbox','Pipeline',i<2?'Reports':'',i===0?'Billing':''].filter(Boolean).map(x=>`<span class="pill">${x}</span>`).join('')}</div></div>`}).join('')}</div>
