const qItem=l=>{const ms=l.sla-now();return`<button type="button" class="q" data-chat="${l.id}">${avS(l)}<div class="t" style="min-width:0"><b>${esc(l.n)}</b> <span class="mu sm-t">· ${esc(l.int)}</span><p>${esc(last(l).t)}</p></div><span class="hide-s mu sm-t">${rel(l.at)} ago</span><span class="sla ${slaCls(ms)}" data-sla="${l.sla}" title="Time left to reply">${slaTx(ms)}</span></button>`};
const thItem=l=>`<button type="button" class="th ${l.id===S.th?'on':''} ${l.un?'un':''}" data-th="${l.id}">${avS(l)}<div class="t"><div class="r1"><b>${esc(l.n)}</b><time>${rel(last(l).at)}</time></div><div class="r1"><p style="flex:1;min-width:0">${last(l).f==='out'?'You: ':''}${esc(last(l).t)}</p>${l.un?'<span class="ud"></span>':''}</div><div class="r1" style="margin-top:6px;gap:6px">${l.draft?'<span class="pill ac">'+ic('spark')+'Draft ready</span>':''}<span class="mu2 sm-t" style="font-size:11px">${BIZ[l.biz].split(' · ')[0]}</span></div></div></button>`;
function convo(c){const ig=c.src==='ig'?'ig':'';let lastDay='';const ms=c.msgs.map(m=>{const d=new Date(m.at).toDateString(),h=d!==lastDay?`<div class="day">${d===new Date().toDateString()?'Today':dstr(m.at)}</div>`:'';lastDay=d;return h+`<div class="bb ${m.f} ${ig}">${esc(m.t).replace(/\n/g,'<br>')}<small>${clk(m.at)}${m.f==='out'?' <span class="ticks">✓✓</span>':''}</small></div>`}).join('');
return`<div class="cv-h"><button class="ib back" type="button" id="back" aria-label="Back to conversations">${ic('back')}</button>${avS(c)}<div style="min-width:0"><b>${esc(c.n)}</b><small>${SRC[c.src][0]} · ${esc(c.ph)}</small></div><div class="r"><button class="btn sm" type="button" data-open="${c.id}">Profile</button></div></div>
<div class="msgs" id="msgs">${ms}</div><div class="comp">${c.draft?`<div class="ai-lab">${ic('spark')}AI draft ready · edit if you like, then approve</div>`:''}<div class="sugg">${SUGG(c).map((s,i)=>`<button type="button" class="chip ${s.k||''}" data-sg="${i}">${s.k?ic('spark'):''}${s.lab}</button>`).join('')}${TPL.map((t,i)=>`<button type="button" class="chip" data-tp="${i}">${ic('note')}${t[0]}</button>`).join('')}</div><div class="cbox"><textarea id="txt" rows="3" aria-label="Reply" placeholder="Write a reply… (sample, nothing is really sent)">${esc(c.draft||'')}</textarea><button class="btn pri" type="button" id="send">${ic('send')}<span>${c.draft?'Approve':'Send'}</span></button></div></div>`}
function details(c){return`<div class="hd">${av(c.n,'l')}<b>${esc(c.n)}</b><p>${esc(c.int)}</p><div style="display:flex;gap:6px;justify-content:center;margin-top:10px"><span class="pill" style="border-color:${STG.find(s=>s[0]===c.st)[2]}66;color:${STG.find(s=>s[0]===c.st)[2]}">${STG.find(s=>s[0]===c.st)[1]}</span>${srcP(c.src)}</div></div>
<dl class="kv"><dt>Business</dt><dd>${BIZ[c.biz].split(' · ')[0]}</dd><dt>Deal value</dt><dd class="num">${inr(c.val)}</dd><dt>Owner</dt><dd>${tm(c.own).n}</dd><dt>Next follow-up</dt><dd>${c.nf?dstr(c.nf)+', '+clk(c.nf):'–'}</dd><dt>First contact</dt><dd>${rel(c.at)} ago</dd></dl>
<div class="sec-t">Tags</div><div class="tags">${c.tags.map(t=>`<span class="pill">${esc(t)}</span>`).join('')||'<span class="mu sm-t">No tags</span>'}</div><div class="sec-t">Latest note</div><p class="sm-t mu">${c.notes[0]?esc(c.notes[0].t):'No notes yet.'}</p><button class="btn sm" type="button" data-open="${c.id}" style="margin-top:16px;width:100%">Open full profile</button>`}
const ageOf=l=>{const d=(now()-l.stAt)/D;return[d<1?Math.max(1,Math.round((now()-l.stAt)/H))+'h':Math.round(d)+'d',d>4?'bad':d>2?'warn':'']};
const lcard=l=>{const[a,c]=ageOf(l);return`<button type="button" class="lc" draggable="true" data-id="${l.id}" data-open="${l.id}"><div class="r1">${avS(l,'s')}<b>${esc(l.n)}</b><span class="val">${inrK(l.val)}</span></div><p>${esc(l.int)}</p><div class="r2">${av(tm(l.own).n,'s',tm(l.own).h)}<span>${BIZ[l.biz].split(' · ')[0]}</span><span class="age ${['won','lost'].includes(l.st)?'':c}" title="Time in this stage"><i></i>${a}</span></div></button>`};
const fuItem=l=>{const ms=l.nf-now();return`<div class="fu" data-fu="${l.id}"><span class="tm">${clk(l.nf)}</span>${avS(l)}<div class="t" style="min-width:0"><b>${esc(l.n)}</b><p>${esc(l.int)} · ${tm(l.own).n.split(' ')[0]}</p></div><span class="cd ${ms<0?'dn':ms<2*H?'':'mu'}" data-cd="${l.nf}">${ms<0?fuLate(ms):'in '+mmss(ms)}</span><div style="display:flex;gap:6px"><button class="btn sm wa" type="button" data-wa="${l.id}" aria-label="Send WhatsApp follow-up to ${esc(l.n)}">${ic('wa')}<span class="hide-s">WhatsApp</span></button><button class="btn sm ghost hide-s" type="button" data-open="${l.id}">Open</button></div></div>`};
// ---------- view actions
const A={
today(V){chartHover(V)},
inbox(V){const m=$('#msgs');if(m)m.scrollTop=m.scrollHeight;const c=byId(S.th);if(c&&c.un&&!S.chatOpenedOnly){}},
pipe(){pbody();$('#pq').addEventListener('input',e=>{S.pq=e.target.value;pbody()});$$('#lv button').forEach(b=>b.onclick=()=>{S.lv=b.dataset.l;save();$$('#lv button').forEach(x=>x.classList.toggle('on',x===b));pbody()})},
auto(){requestAnimationFrame(drawGraph)}};
function pbody(){const q=(S.pq||'').toLowerCase(),ls=L().filter(l=>!q||(l.n+' '+l.int+' '+l.tags.join(' ')).toLowerCase().includes(q)),B=$('#pbody');if(!B)return;
if(S.lv==='table'){B.innerHTML=`<div class="panel" style="overflow-x:auto"><table class="tbl"><thead><tr><th>Lead</th><th>Stage</th><th class="hide-s">Source</th><th>Value</th><th class="hide-s">Owner</th><th class="hide-s">Last touch</th></tr></thead><tbody>${ls.map(l=>{const s=STG.find(x=>x[0]===l.st);return`<tr class="rw" data-open="${l.id}" tabindex="0"><td><span class="who">${av(l.n,'s')}<b>${esc(l.n)}</b></span></td><td><span class="pill"><i style="background:${s[2]}"></i>${s[1]}</span></td><td class="hide-s">${srcP(l.src)}</td><td class="num">${inrK(l.val)}</td><td class="hide-s">${tm(l.own).n}</td><td class="hide-s mu">${rel(last(l).at)} ago</td></tr>`}).join('')}</tbody></table></div>`;return}
B.innerHTML=`<div class="kan">${STG.map(s=>{const a=ls.filter(l=>l.st===s[0]),v=a.reduce((x,l)=>x+l.val,0),mx=Math.max(1,...STG.map(t=>ls.filter(l=>l.st===t[0]).reduce((x,l)=>x+l.val,0)));return`<div class="col" data-st="${s[0]}"><div class="col-h"><i style="background:${s[2]}"></i><b>${s[1]}</b><span class="c">${a.length}</span><span class="vv">${inrK(v)}</span></div><div class="col-bar"><span style="width:${v/mx*100}%;background:${s[2]}"></span></div><div class="cards">${a.map(lcard).join('')||'<div class="empty-c">Drop a lead here</div>'}</div></div>`}).join('')}</div>`;
let dragId=null;$$('.lc',B).forEach(c=>{c.addEventListener('dragstart',e=>{dragId=c.dataset.id;c.classList.add('drag');e.dataTransfer.setData('text/plain',dragId);e.dataTransfer.effectAllowed='move'});c.addEventListener('dragend',()=>c.classList.remove('drag'))});
$$('.col',B).forEach(col=>{col.addEventListener('dragover',e=>{e.preventDefault();col.classList.add('over')});col.addEventListener('dragleave',()=>col.classList.remove('over'));col.addEventListener('drop',e=>{e.preventDefault();col.classList.remove('over');const l=byId(e.dataTransfer.getData('text/plain')||dragId);if(l&&l.st!==col.dataset.st)moveStage(l,col.dataset.st)})})}
function moveStage(l,st){const s=STG.find(x=>x[0]===st);l.st=st;l.stAt=now();l.tl.push({k:st==='won'?'won':'stage',t:`Moved to ${s[1]}${st==='won'?' 🎉':''}`,at:now()});if(['won','lost'].includes(st))l.nf=null;save();toast(st==='won'?'Deal won 🎉':'Stage updated',`${l.n} → ${s[1]}`);if(S.view==='pipe'){pbody();const c=$(`.lc[data-id="${l.id}"]`);c&&c.classList.add('enter')}navs()}
function chartHover(V){const ch=$('.chart',V);if(!ch)return;const svg=$('svg',ch),tip=$('.tip',ch),dot=$('.dotc',ch),pts=ch.dataset.pts.split(',').map(Number),lab=ch.dataset.lab.split('|');const vb=svg.viewBox.baseVal,mx=Math.max(...pts,11)*1.15;
const mv=e=>{const r=svg.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,i=Math.round(x*(pts.length-1));if(i<0||i>=pts.length)return;const cx=i*vb.width/(pts.length-1),cy=vb.height-24-(pts[i]/Math.max(...pts,...[11])/1.15)*(vb.height-40);dot.setAttribute('cx',cx);dot.setAttribute('cy',cy);tip.style.left=(cx/vb.width*r.width)+'px';tip.style.top=(cy/vb.height*r.height)+'px';tip.innerHTML=`<b>${pts[i]} leads</b> <span class="mu">· ${lab[i]}</span>`;tip.style.opacity=1};
ch.addEventListener('pointermove',mv);ch.addEventListener('pointerleave',()=>{tip.style.opacity=0;dot.setAttribute('cx',-20)})}
function drawGraph(){const g=$('#graph'),s=$('#gsvg');if(!g||!s)return;const cr=s.getBoundingClientRect(),ns=$$('.node',g);let d='';
for(let i=0;i<ns.length-1;i++){const a=ns[i].getBoundingClientRect(),b=ns[i+1].getBoundingClientRect();let x1,y1,x2,y2,p;
if(Math.abs(a.top-b.top)<10){const rv=b.left<a.left;x1=(rv?a.left:a.right)-cr.left;y1=a.top+a.height/2-cr.top;x2=(rv?b.right:b.left)-cr.left;y2=b.top+b.height/2-cr.top;const c=(x2-x1)/2;p=`M${x1},${y1} C${x1+c},${y1} ${x2-c},${y2} ${x2},${y2}`}
else{x1=a.left+a.width/2-cr.left;y1=a.bottom-cr.top;x2=b.left+b.width/2-cr.left;y2=b.top-cr.top;const c=(y2-y1)/2;p=`M${x1},${y1} C${x1},${y1+c} ${x2},${y2-c} ${x2},${y2}`}
d+=`<path d="${p}"/><path class="flow" d="${p}"/><circle cx="${x2}" cy="${y2}" r="3" fill="#111827"/>`}
s.setAttribute('viewBox',`0 0 ${cr.width} ${cr.height}`);s.innerHTML=d}
addEventListener('resize',()=>{if(S.view==='auto')drawGraph()});
// ---------- drawer
