const evs=[...l.tl.map(e=>({...e})),...l.msgs.slice(1).map(m=>({k:m.f,t:(m.f==='in'?'Customer: ':'You: ')+m.t,at:m.at})),...l.notes.map(n=>({k:'note',t:'Note: '+n.t,at:n.at}))].sort((a,b)=>b.at-a.at);
const kc={in:'#2F6FD0',out:'#16A34A',stage:'#94A3B8',won:'#B8913F',note:'#64748B'};
D2.innerHTML=`<div class="dr-h">${avS(l,'l')}<div style="min-width:0"><b>${esc(l.n)}</b><small>${esc(l.int)} · ${BIZ[l.biz]}</small></div><button class="ib x" type="button" id="drX" aria-label="Close">${ic('x')}</button></div><div class="dr-b">
<div class="dr-act"><button class="btn wa" type="button" data-wa="${l.id}">${ic('wa')}WhatsApp</button><button class="btn" type="button" data-chat="${l.id}">${ic('inbox')}Chat</button><button class="btn" type="button" id="callB">${ic('call')}Call</button></div>
<div class="nf">${ic('clock')}<div style="flex:1"><b>${l.nf?'Next follow-up '+(l.nf<now()?'(overdue)':''):'No follow-up planned'}</b><small>${l.nf?dstr(l.nf)+', '+clk(l.nf):'Pick a time below'}</small></div><select class="inp" id="nfSel" aria-label="Plan follow-up" style="height:30px;font-size:12px"><option value="">Plan…</option><option value="2">In 2 hours</option><option value="24">Tomorrow</option><option value="72">In 3 days</option></select></div>
<dl class="kv" style="padding-top:0"><dt>Stage</dt><dd><select class="inp" id="stSel" aria-label="Stage" style="height:30px;font-size:12px">${STG.map(x=>`<option value="${x[0]}" ${x[0]===l.st?'selected':''}>${x[1]}</option>`).join('')}</select></dd><dt>Deal value</dt><dd class="num">${inr(l.val)}</dd><dt>Owner</dt><dd>${tm(l.own).n}</dd><dt>Phone</dt><dd>${esc(l.ph)}</dd><dt>Source</dt><dd>${SRC[l.src][0]}</dd></dl>
<div class="sec-t">Tags</div><div class="tags" id="tags">${l.tags.map(t=>`<span class="pill">${ic('tag')}${esc(t)}</span>`).join('')}<button class="chip" type="button" id="addTag" style="height:20px;font-size:11px">+ Tag</button></div>
<div class="sec-t">Add a note</div><div class="cbox"><textarea id="noteT" rows="1" placeholder="e.g. Wants Saturday morning slot" aria-label="Note"></textarea><button class="btn sm" type="button" id="noteB">Save</button></div>
<div class="sec-t">Timeline · every touch</div><div class="tl">${evs.map(e=>`<div class="e" style="--k:${kc[e.k]||'#777'}"><p>${esc(e.t)}</p><small>${dstr(e.at)}, ${clk(e.at)}</small></div>`).join('')}</div></div>`;
D2.hidden=false;$('#scrim').hidden=false;D2.dataset.id=id;setTimeout(()=>$('#drX').focus(),50);
$('#drX').onclick=closeAll;$('#stSel').onchange=e=>{moveStage(l,e.target.value);openLead(id)};$('#nfSel').onchange=e=>{if(!e.target.value)return;l.nf=now()+e.target.value*H;l.tl.push({k:'stage',t:'Follow-up planned',at:now()});save();toast('Follow-up planned',`${l.n} · ${dstr(l.nf)}, ${clk(l.nf)}`);openLead(id);render()};
$('#noteB').onclick=()=>{const t=$('#noteT').value.trim();if(!t)return;l.notes.unshift({t,at:now(),by:'sk'});save();toast('Note saved',t);openLead(id)};
