function openChat(id){S.th=id;S.chat=true;const l=byId(id);if(l)l.un=false;save();if(S.view!=='inbox')go('inbox');else render();}
function sendMsg(){const l=byId(S.th),ta=$('#txt');if(!l||!ta)return;const t=ta.value.trim();if(!t){ta.focus();return}l.msgs.push({f:'out',t,at:now()});l.tl.push({k:'out',t:l.draft?'Approved AI draft and sent':'Reply sent',at:now()});l.draft=null;l.un=false;l.sla=null;if(l.st==='new'){l.st='contacted';l.stAt=now()}if(!l.nf)l.nf=now()+24*H;save();render();toast('Sent on '+SRC[l.src][0]+' (sample)',`To ${l.n}`);
if(Math.random()<.9)setTimeout(()=>{if(S.view!=='inbox'||S.th!==l.id)return;const m=$('#msgs');if(!m)return;const ty=document.createElement('div');ty.className='typing';ty.innerHTML='<i></i><i></i><i></i>';m.append(ty);m.scrollTop=m.scrollHeight;setTimeout(()=>{ty.remove();l.msgs.push({f:'in',t:['Thank you! 🙏 Kal aate hain','Ok perfect, details mil gaye','Great, Saturday confirm kar do','👍'][Math.floor(Math.random()*4)],at:now()});save();if(S.view==='inbox'&&S.th===l.id)render()},1800)},900)}
function typeInto(ta,text){ta.value='';let i=0;const st=()=>{i+=Math.max(1,Math.round(text.length/40));ta.value=text.slice(0,i);if(i<text.length)requestAnimationFrame(st)};st();ta.focus()}
