let liveT;function live(){clearTimeout(liveT);if(!S.live)return;liveT=setTimeout(()=>{addLead();live()},first?2600:10000);first=false}
function addLead(){const d=NEW[S.ni%NEW.length];S.ni++;const [n,biz,src,int,val,m]=d;if(S.biz&&S.biz!==biz){S.ni=S.ni;}const id='N'+S.ni+'_'+now().toString(36);const t=now();
const l={id,n,biz,src,st:'new',int,val,own:TEAM[S.ni%4].id,tags:[],msgs:[{f:'in',t:m,at:t}],tl:[{k:'in',t:`Enquiry via ${SRC[src][0]}`,at:t}],nf:null,at:t,stAt:t,ph:'+91 98'+(10+S.ni%80)+'4 '+(20000+S.ni*731),un:true,draft:null,sla:t+15*M,notes:[]};
S.leads.unshift(l);S.notif.unshift({u:true,t:`New lead: ${n}`,s:`${SRC[src][0]} · ${int}`,id,at:t});S.notif=S.notif.slice(0,8);if(S.leads.length>60)S.leads.pop();save();
setTimeout(()=>{l.draft=draftFor(l);save();if(S.view==='inbox'&&S.th===id)render()},2200);
if(!S.biz||S.biz===biz){toastLead(l);navs(true);
 if(S.view==='today'){const q=$('#queue');if(q){const w=document.createElement('div');w.innerHTML=qItem(l);const el=w.firstChild;el.classList.add('enter');if(q.querySelector('.pb'))q.innerHTML='';q.prepend(el);while(q.children.length>6)q.lastChild.remove();const h=$('.hero-t em');if(h)h.textContent=`${L().filter(x=>x.un).length} people are waiting for a reply.`}}
 else if(S.view==='inbox'){const il=$('#ilist');if(il&&(S.ibf||'all')!=='un'||true){const w=document.createElement('div');w.innerHTML=thItem(l);const el=w.firstChild;el.classList.add('enter');il&&il.prepend(el)}}
 else if(S.view==='pipe'&&S.lv==='kanban'){const c=$('.col[data-st="new"] .cards');if(c){const e=c.querySelector('.empty-c');e&&e.remove();const w=document.createElement('div');w.innerHTML=lcard(l);const el=w.firstChild;el.classList.add('enter');c.prepend(el);pbody();const n2=$(`.lc[data-id="${id}"]`);n2&&n2.classList.add('enter')}}}
}
function toastLead(l){const t=document.createElement('div');t.className='toast';t.innerHTML=`${avS(l)}<div style="min-width:0;flex:1"><b>New ${SRC[l.src][0]} lead · ${esc(l.n)}</b><small>${esc(l.msgs[0].t)}</small></div><button class="btn sm" type="button" data-chat="${l.id}">Reply</button>`;$('#toasts').append(t);setTimeout(()=>{t.classList.add('out');setTimeout(()=>t.remove(),300)},5200)}
